      "status": "explicit"
    },
    {
      "req_id": "R2",
      "statement": "Each job must be assigned to exactly one worker.",
      "source_refs": [
        "problem_statement:business_rules_2"
      ],
      "scope": "job",
      "units": "count",
      "hardness": "hard",
      "status": "explicit"
    },
    {
      "req_id": "R3",
      "statement": "Worker W2 cannot be assigned to Job J3.",
      "source_refs": [
        "problem_statement:business_rules_3"
      ],
      "scope": "pair(W2, J3)",
      "units": "boolean",
      "hardness": "hard",
      "status": "explicit"
    },
    {
      "req_id": "R4",
      "statement": "Minimize the total cost of assignments based on data/costs.csv.",
      "source_refs": [
        "problem_statement:objective",
        "data/costs.csv"
      ],
      "scope": "global",
      "units": "cost",
      "hardness": "soft",
      "status": "explicit"
    },
    {
      "req_id": "R5",
      "statement": "Output solution.json in the program directory with keys 'objective' and 'assignments'.",
      "source_refs": [
        "problem_statement:output_requirements"
      ],
      "scope": "file",
      "units": "json",
      "hardness": "hard",
      "status": "explicit"
    },
    {
      "req_id": "R6",
      "statement": "Print 'OBJECTIVE <total_cost>' to standard output.",
      "source_refs": [
        "problem_statement:output_requirements"
      ],
      "scope": "stdout",
      "units": "string",
      "hardness": "hard",
      "status": "explicit"
    }
  ],
  "findings": [
    {
      "req_ids": [
        "R3"
      ],
      "problem_type": "implementation",
      "detail": "The code does not enforce the constraint that Worker W2 cannot be assigned to Job J3. The variable x['W2', 'J3'] is created and included in the objective function without being fixed to 0 or constrained to be 0. Since the cost for (W2, J3) is 1 (the lowest in the matrix), the solver will likely assign this pair, violating the business rule.",
      "evidence_level": "llm_judgment",
      "status": "suspected",
      "proposed_checks": [
        "python3 -c \"import json; d=json.load(open('/app/solution.json')); assert not any(a['worker']=='W2' and a['job']=='J3' for a in d['assignments']), 'W2 assigned to J3'; print('PASS')\"",
        "grep -n \"W2.*J3\\|x\\['W2', 'J3'\\]\" /app/submissions/solve.py | grep -v \"#\""
      ]
    }
  ]
}
